-- Read-only PG proof checks; acknowledgement evidence is not a live Redis audit.
SELECT json_build_object(
 'linked_identity_mismatch',(SELECT count(*) FROM stock_hold_acceptance a JOIN stock_hold_intent i ON i.id=a.intent_id JOIN purchase_request p ON p.id=a.purchase_id WHERE ROW(i.customer_id,i.request_id,i.ticket_id,i.quantity,i.ticket_version,i.total_twd,i.session_version,i.session_hash,i.deadline_at) IS DISTINCT FROM ROW(p.customer_id,p.request_id,p.ticket_id,p.quantity,p.ticket_version,p.total_twd,p.session_version,p.session_hash,p.deadline_at)),
 'missing_original_command',(SELECT count(*) FROM stock_hold_acceptance a JOIN purchase_request p ON p.id=a.purchase_id WHERE NOT EXISTS(SELECT 1 FROM purchase_command c WHERE c.customer_id=p.customer_id AND c.request_id=p.request_id AND c.action='SUBMIT' AND c.purchase_id=p.id AND c.fingerprint=p.fingerprint)),
 'missing_outbox',(SELECT count(*) FROM stock_hold_acceptance a WHERE NOT EXISTS(SELECT 1 FROM purchase_outbox o WHERE o.purchase_id=a.purchase_id)),
 'accepted_progress_mismatch',(SELECT count(*) FROM stock_hold_acceptance a JOIN stock_hold_progress p ON p.intent_id=a.intent_id WHERE p.state<>'HELD'),
 'terminal_decision_missing',(SELECT count(*) FROM stock_hold_acceptance a JOIN purchase_request p ON p.id=a.purchase_id LEFT JOIN stock_hold_decision d ON d.intent_id=a.intent_id WHERE (p.status='PROCESSING')<>(d.intent_id IS NULL)),
 'decision_result_mismatch',(SELECT count(*) FROM stock_hold_decision d JOIN stock_hold_acceptance a ON a.intent_id=d.intent_id JOIN purchase_request p ON p.id=a.purchase_id WHERE d.purchase_status<>p.status OR d.order_id IS DISTINCT FROM p.order_id OR d.reason IS DISTINCT FROM COALESCE(p.reason,'FORMAL_RESERVATION_COMMITTED') OR (d.target='COMMIT')<>(p.status='RESERVED')),
 'commit_order_proof_missing',(SELECT count(*) FROM stock_hold_decision d JOIN stock_hold_acceptance a ON a.intent_id=d.intent_id JOIN purchase_request p ON p.id=a.purchase_id WHERE d.target='COMMIT' AND NOT EXISTS(SELECT 1 FROM ticket_order o JOIN order_inventory_event e ON e.order_id=o.id AND e.phase='HOLD' WHERE o.id=d.order_id AND ROW(o.customer_id,o.request_id,o.ticket_id,o.quantity,o.total_twd)=ROW(p.customer_id,p.request_id,p.ticket_id,p.quantity,p.total_twd) AND e.ticket_id=o.ticket_id AND e.delta=o.quantity)),
 'release_has_formal_order',(SELECT count(*) FROM stock_hold_decision d JOIN stock_hold_intent i ON i.id=d.intent_id WHERE d.target='RELEASE' AND EXISTS(SELECT 1 FROM ticket_order o WHERE o.customer_id=i.customer_id AND o.request_id=i.request_id)),
 'contradictory_ack',(SELECT count(*) FROM stock_hold_ack a JOIN stock_hold_decision d ON d.intent_id=a.intent_id WHERE (d.target='COMMIT' AND a.resolution='RELEASED') OR (d.target='RELEASE' AND a.resolution='COMMITTED')),
 'acknowledged_epoch_open',(SELECT count(*) FROM stock_hold_ack a JOIN stock_hold_intent i ON i.id=a.intent_id JOIN stock_projection g ON g.ticket_id=i.ticket_id WHERE i.generation=g.generation AND g.state<>'DIRTY')
);
